<template><div class="folder-summary" aria-label="Informações da pasta"><span><i class="mdi mdi-music-note"/> {{ stats.count }} faixas</span><span><i class="mdi mdi-clock-outline"/> {{ stats.duration ? formatDuration(stats.duration) : 'Duração não informada' }}<small v-if="stats.missingDuration"> · {{ stats.missingDuration }} sem duração</small></span><span><i class="mdi mdi-harddisk"/> {{ stats.bytes ? formatBytes(stats.bytes) : 'Tamanho não informado' }}<small v-if="stats.missingSize"> · {{ stats.missingSize }} sem tamanho</small></span></div></template>
<script setup>import { computed } from 'vue';import { folderStats,formatDuration,formatBytes } from '@/utils/music-library.mjs';const props=defineProps({tracks:{type:Array,default:()=>[]}});const stats=computed(()=>folderStats(props.tracks))</script>
<style scoped>.folder-summary{display:flex;gap:8px 18px;flex-wrap:wrap;color:#bad6c9;font-size:13px;margin:12px 0}.folder-summary span{display:block}.folder-summary small{color:#abb1b9}</style>